<?php
require_once __DIR__ . '/includes/functions.php';
$query=trim((string)($_GET['q']??''));$courses=[];$articles=[];
if($query!==''){$term='%'.$query.'%';$stmt=db()->prepare('SELECT c.id,c.name,c.level,c.duration,d.name AS department FROM courses c JOIN departments d ON d.id=c.department_id WHERE c.status="published" AND (c.name LIKE ? OR c.description LIKE ? OR d.name LIKE ? OR c.level LIKE ?) ORDER BY c.featured DESC,c.name LIMIT 30');$stmt->execute([$term,$term,$term,$term]);$courses=$stmt->fetchAll();$stmt=db()->prepare('SELECT id,title,excerpt,category,published_at FROM news WHERE status="published" AND (title LIKE ? OR excerpt LIKE ? OR content LIKE ? OR category LIKE ?) ORDER BY published_at DESC LIMIT 20');$stmt->execute([$term,$term,$term,$term]);$articles=$stmt->fetchAll();}
$pageTitle='Search TTVC';include __DIR__.'/includes/header.php';
?><section class="page-hero"><div class="container"><p class="eyebrow">Find it at TTVC</p><h1>Search courses<br>and news.</h1></div></section><section class="content-section container"><form class="search-row" method="get"><input class="search-field" name="q" type="search" placeholder="ICT, Diploma, admissions…" value="<?= e($query) ?>" autofocus><button class="button">Search</button></form><?php if($query!==''):?><h2>Courses (<?= count($courses) ?>)</h2><div class="result-list"><?php foreach($courses as $course):?><article class="result-row"><div><h3><?= e($course['name']) ?></h3><p><?= e($course['department']) ?> · <?= e($course['level']) ?> · <?= e($course['duration']) ?></p></div><a class="text-link" href="<?= e(url('course-details.php?id='.$course['id'])) ?>">View course <span>→</span></a></article><?php endforeach;?><?php if(!$courses):?><p class="empty-state">No matching courses.</p><?php endif;?></div><h2 style="margin-top:40px">News (<?= count($articles) ?>)</h2><div class="result-list"><?php foreach($articles as $article):?><article class="result-row"><div><h3><?= e($article['title']) ?></h3><p><?= e($article['category']) ?> · <?= e(date('d M Y',strtotime($article['published_at']))) ?> · <?= e($article['excerpt']) ?></p></div><a class="text-link" href="<?= e(url('news-details.php?id='.$article['id'])) ?>">Read story <span>→</span></a></article><?php endforeach;?><?php if(!$articles):?><p class="empty-state">No matching stories.</p><?php endif;?></div><?php endif;?></section><?php include __DIR__.'/includes/footer.php';?>